def transform(grid):
    colors = {value for row in grid for value in row}
    if len(colors) != 2 or 5 not in colors:
        raise ValueError('expected two colors including 5')
    other = next(color for color in colors if color != 5)
    return [[other if value == 5 else 0 for value in row] for row in grid]
